def is_distribution(p):
    if any(x < 0 for x in p):
        return False
    return abs(sum(p) - 1) < 1e-9

def sample(p, u):
    total = 0
    for i, pi in enumerate(p):
        total += pi
        if u < total:
            return i
    return len(p) - 1

import numpy as np

def frequencies(rolls):
    counts = np.bincount(rolls - 1, minlength=6)
    return counts / len(rolls)
